"""Render reviewable per-node netplan for all four logical RoCE interfaces."""

from __future__ import annotations

from .model import PairConfig


def render_netplan(config: PairConfig, role: str) -> str:
    config.node(role)  # validate role
    lines = [
        "# Generated by spark-four-hca. Review before installing.",
        "# No gateway or default route is created on the point-to-point fabric.",
        "network:",
        "  version: 2",
        "  renderer: NetworkManager",
        "  ethernets:",
    ]
    for path in sorted(config.paths, key=lambda item: (item.physical_port, item.pcie_domain)):
        address = path.address_for(role)
        lines.extend(
            [
                f"    {path.netdev}:",
                "      addresses:",
                f"        - {address}",
                "      dhcp4: false",
                "      dhcp6: false",
                f"      mtu: {config.mtu}",
                "      link-local: [ipv6]",
            ]
        )
    return "\n".join(lines) + "\n"


def render_topology(config: PairConfig) -> str:
    lines = [
        f"Pair: {config.pair_label}",
        "",
        "path            cage  PCIe domain  netdev              RDMA device       head              worker",
        "--------------- ----- ------------ ------------------- ----------------- ----------------- -----------------",
    ]
    for path in sorted(config.paths, key=lambda item: (item.physical_port, item.pcie_domain)):
        lines.append(
            f"{path.name:<15} {path.physical_port:<5} {path.pcie_domain:<12} "
            f"{path.netdev:<19} {path.rdma_device:<17} "
            f"{str(path.head_address):<17} {str(path.worker_address):<17}"
        )
    lines.extend(["", "Benchmark modes:"])
    for mode, members in config.modes.items():
        selected = [config.paths_by_name[name] for name in members]
        ports = sorted({item.physical_port for item in selected})
        domains = sorted({item.pcie_domain for item in selected})
        lines.append(
            f"  {mode:<18} paths={','.join(members):<31} cages={ports} domains={domains}"
        )
    return "\n".join(lines) + "\n"
